  def read_fixed_vec(data, num_bits) when is_binary(data) and is_integer(num_bits) do
    try do
      if num_bits > byte_size(data) * 8 do
        # the payload cannot exceed the buffer behind it
        throw(:invalid)
      end

      bits_read = 0
      if bits_read + 102 > num_bits, do: throw(:invalid)
      rv = rdw(data, bits_read, 49)
      v = rv &&& 0xFFFFFFFF
      bits_read = bits_read + 32
      w = v
      v = rv >>> 32 &&& 0x3
      bits_read = bits_read + 2
      w = w ||| v <<< 32
      # a smuggled offset is refused
      if w > 13_107_200_000, do: throw(:invalid)
      v_x = w - 6_553_600_000
      rv = rdw(data, bits_read, 49)
      v = rv &&& 0xFFFFFFFF
      bits_read = bits_read + 32
      w = v
      v = rv >>> 32 &&& 0x3
      bits_read = bits_read + 2
      w = w ||| v <<< 32
      # a smuggled offset is refused
      if w > 13_107_200_000, do: throw(:invalid)
      v_y = w - 6_553_600_000
      rv = rdw(data, bits_read, 34)
      v = rv &&& 0xFFFFFFFF
      bits_read = bits_read + 32
      w = v
      v = rv >>> 32
      bits_read = bits_read + 2
      w = w ||| v <<< 32
      # a smuggled offset is refused
      if w > 13_107_200_000, do: throw(:invalid)
      v_z = w - 6_553_600_000
      # the final position is unobserved — the verdict and value are the surface
      _ = bits_read
      value = %Ludicrous.FixedVec{x: v_x, y: v_y, z: v_z}
      {:ok, value}
    catch
      :invalid -> :error
    end
  end

  # measure_fixed_vec is the exact wire bits write_fixed_vec would produce for value —
  # trusted like the writer; static runs fold to literals at generation time.
  def measure_fixed_vec(_value), do: 102

  # fixed_quat_max_bits is the longest wire path; align pads at worst case (SPEC §6.1).
  # fixed_quat_max_bytes is rounded up to the family 8-byte write-buffer granularity.
  def fixed_quat_max_bits, do: 128
  def fixed_quat_max_bytes, do: 16

  # The §5 zero form: all-zero storage; specified defaults live only in
  # construction (%Ludicrous.FixedQuat{}).
  def zero_fixed_quat, do: %Ludicrous.FixedQuat{x: 0, y: 0, z: 0, w: 0}

  # write_fixed_quat packs value into a fresh binary — the trusted writer; the O(1)
  # contract checks raise ArgumentError, always on (the BEAM has no
  # compile-out assert). Returns the wire bytes.
  def write_fixed_quat(value) do
    data = <<>>
    %{x: value_x, y: value_y, z: value_z, w: value_w} = value

    if value_x < -1_073_741_824 do
      raise ArgumentError, "value.x is below the wire minimum"
    end

    if value_x > 1_073_741_824 do
      raise ArgumentError, "value.x is above the wire maximum"
    end

    v = value_x + 1_073_741_824
    scratch = v

    if value_y < -1_073_741_824 do
      raise ArgumentError, "value.y is below the wire minimum"
    end

    if value_y > 1_073_741_824 do
      raise ArgumentError, "value.y is above the wire maximum"
    end

    v = value_y + 1_073_741_824
    sc0 = scratch
    scratch = v

    if value_z < -1_073_741_824 do
      raise ArgumentError, "value.z is below the wire minimum"
    end

    if value_z > 1_073_741_824 do
      raise ArgumentError, "value.z is above the wire maximum"
    end

    v = value_z + 1_073_741_824
    sc1 = scratch
    scratch = v

    if value_w < -1_073_741_824 do
      raise ArgumentError, "value.w is below the wire minimum"
    end

    if value_w > 1_073_741_824 do
      raise ArgumentError, "value.w is above the wire maximum"
    end

    v = value_w + 1_073_741_824
    sc2 = scratch
    scratch = v

    data =
      <<data::binary, sc0::little-size(4)-unit(8), sc1::little-size(4)-unit(8),
        sc2::little-size(4)-unit(8), scratch::little-size(4)-unit(8)>>

    data
  end

  # read_fixed_quat decodes the first num_bits of data — the family read verdict:
  # :error rejects the wire (bounds, ranges, wire constants, padding);
  # hostile bytes never raise. No slack past the payload is required.
  def read_fixed_quat(data, num_bits) when is_binary(data) and is_integer(num_bits) do
    try do
      if num_bits > byte_size(data) * 8 do
        # the payload cannot exceed the buffer behind it
        throw(:invalid)
      end

      bits_read = 0
      if bits_read + 128 > num_bits, do: throw(:invalid)
      rv = rdw(data, bits_read, 49)
      v = rv &&& 0xFFFFFFFF
      bits_read = bits_read + 32
      # a smuggled offset is refused
      if v > 2_147_483_648, do: throw(:invalid)
      v_x = v - 1_073_741_824
      rv = rdw(data, bits_read, 49)
      v = rv &&& 0xFFFFFFFF
      bits_read = bits_read + 32
      # a smuggled offset is refused
      if v > 2_147_483_648, do: throw(:invalid)
      v_y = v - 1_073_741_824
      rv = rdw(data, bits_read, 49)
      v = rv &&& 0xFFFFFFFF
      bits_read = bits_read + 32
      # a smuggled offset is refused
      if v > 2_147_483_648, do: throw(:invalid)
      v_z = v - 1_073_741_824
      rv = rd(data, bits_read, 32)
      v = rv
      bits_read = bits_read + 32
      # a smuggled offset is refused
      if v > 2_147_483_648, do: throw(:invalid)
      v_w = v - 1_073_741_824
      # the final position is unobserved — the verdict and value are the surface
      _ = bits_read
      value = %Ludicrous.FixedQuat{x: v_x, y: v_y, z: v_z, w: v_w}
      {:ok, value}
    catch
      :invalid -> :error
    end
  end

  # measure_fixed_quat is the exact wire bits write_fixed_quat would produce for value —
  # trusted like the writer; static runs fold to literals at generation time.
  def measure_fixed_quat(_value), do: 128

  defp w_fixed_probe_samples([], data, scratch, scratch_bits), do: {data, scratch, scratch_bits}

  defp w_fixed_probe_samples([e1, e2, e3, e4 | rest], data, scratch, scratch_bits) do
    if e1 < -524_288 do
      raise ArgumentError, "e is below the wire minimum"
    end

    if e1 > 524_288 do
      raise ArgumentError, "e is above the wire maximum"
    end

    v = e1 + 524_288
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 21

    if e2 < -524_288 do
      raise ArgumentError, "e is below the wire minimum"
    end

    if e2 > 524_288 do
      raise ArgumentError, "e is above the wire maximum"
    end

    v = e2 + 524_288
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 21

    if e3 < -524_288 do
      raise ArgumentError, "e is below the wire minimum"
    end

    if e3 > 524_288 do
      raise ArgumentError, "e is above the wire maximum"
    end

    v = e3 + 524_288
    sc0 = scratch
    fl0 = scratch_bits >>> 3
    scratch = scratch >>> (fl0 <<< 3)
    scratch_bits = scratch_bits &&& 7
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 21

    if e4 < -524_288 do
      raise ArgumentError, "e is below the wire minimum"
    end

    if e4 > 524_288 do
      raise ArgumentError, "e is above the wire maximum"
    end

    v = e4 + 524_288
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 21
    flush = scratch_bits >>> 3
    data = <<data::binary, sc0::little-size(fl0)-unit(8), scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    w_fixed_probe_samples(rest, data, scratch, scratch_bits)
  end

  defp w_fixed_probe_samples([e | rest], data, scratch, scratch_bits) do
    if e < -524_288 do
      raise ArgumentError, "e is below the wire minimum"
    end

    if e > 524_288 do
      raise ArgumentError, "e is above the wire maximum"
    end

    v = e + 524_288
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 21
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    w_fixed_probe_samples(rest, data, scratch, scratch_bits)
  end

  defp r_fixed_probe_samples(0, acc, _data, _num_bits, bits_read),
    do: {bits_read, Enum.reverse(acc)}

  defp r_fixed_probe_samples(remaining, acc, data, num_bits, bits_read)
       when remaining >= 2 do
    rv = rdw(data, bits_read, 42)
    v = rv &&& 0x1FFFFF
    bits_read = bits_read + 21
    # a smuggled offset is refused
    if v > 1_048_576, do: throw(:invalid)
    e1 = v - 524_288
    v = rv >>> 21
    bits_read = bits_read + 21
    # a smuggled offset is refused
    if v > 1_048_576, do: throw(:invalid)
    e2 = v - 524_288
    r_fixed_probe_samples(remaining - 2, [e2, e1 | acc], data, num_bits, bits_read)
  end

  defp r_fixed_probe_samples(remaining, acc, data, num_bits, bits_read) do
    rv = rd(data, bits_read, 21)
    v = rv
    bits_read = bits_read + 21
    # a smuggled offset is refused
    if v > 1_048_576, do: throw(:invalid)
    e = v - 524_288
    r_fixed_probe_samples(remaining - 1, [e | acc], data, num_bits, bits_read)
  end

  defp w_unsigned_probe_samples([], data, scratch, scratch_bits),
    do: {data, scratch, scratch_bits}

  defp w_unsigned_probe_samples([e1, e2, e3, e4 | rest], data, scratch, scratch_bits) do
    if e1 < 0 do
      raise ArgumentError, "e is below the wire minimum"
    end

    if e1 > 1_048_576 do
      raise ArgumentError, "e is above the wire maximum"
    end

    v = e1
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 21

    if e2 < 0 do
      raise ArgumentError, "e is below the wire minimum"
    end

    if e2 > 1_048_576 do
      raise ArgumentError, "e is above the wire maximum"
    end

    v = e2
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 21

    if e3 < 0 do
      raise ArgumentError, "e is below the wire minimum"
    end

    if e3 > 1_048_576 do
      raise ArgumentError, "e is above the wire maximum"
    end

    v = e3
    sc0 = scratch
    fl0 = scratch_bits >>> 3
    scratch = scratch >>> (fl0 <<< 3)
    scratch_bits = scratch_bits &&& 7
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 21

    if e4 < 0 do
      raise ArgumentError, "e is below the wire minimum"
    end

    if e4 > 1_048_576 do
      raise ArgumentError, "e is above the wire maximum"
    end

    v = e4
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 21
    flush = scratch_bits >>> 3
    data = <<data::binary, sc0::little-size(fl0)-unit(8), scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    w_unsigned_probe_samples(rest, data, scratch, scratch_bits)
  end

  defp w_unsigned_probe_samples([e | rest], data, scratch, scratch_bits) do
    if e < 0 do
      raise ArgumentError, "e is below the wire minimum"
    end

    if e > 1_048_576 do
      raise ArgumentError, "e is above the wire maximum"
    end

    v = e
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 21
    flush = scratch_bits >>> 3
    data = <<data::binary, scratch::little-size(flush)-unit(8)>>
    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    w_unsigned_probe_samples(rest, data, scratch, scratch_bits)
  end

  defp r_unsigned_probe_samples(0, acc, _data, _num_bits, bits_read),
    do: {bits_read, Enum.reverse(acc)}

  defp r_unsigned_probe_samples(remaining, acc, data, num_bits, bits_read)
       when remaining >= 2 do
    rv = rdw(data, bits_read, 42)
    v = rv &&& 0x1FFFFF
    bits_read = bits_read + 21
    # a smuggled offset is refused
    if v > 1_048_576, do: throw(:invalid)
    e1 = v
    v = rv >>> 21
    bits_read = bits_read + 21
    # a smuggled offset is refused
    if v > 1_048_576, do: throw(:invalid)
    e2 = v
    r_unsigned_probe_samples(remaining - 2, [e2, e1 | acc], data, num_bits, bits_read)
  end

  defp r_unsigned_probe_samples(remaining, acc, data, num_bits, bits_read) do
    rv = rd(data, bits_read, 21)
    v = rv
    bits_read = bits_read + 21
    # a smuggled offset is refused
    if v > 1_048_576, do: throw(:invalid)
    e = v
    r_unsigned_probe_samples(remaining - 1, [e | acc], data, num_bits, bits_read)
  end

  defp w_ludicrous_state_keys([], data, scratch, scratch_bits), do: {data, scratch, scratch_bits}

  defp w_ludicrous_state_keys([e | rest], data, scratch, scratch_bits) do
    v = e &&& 0xFFFFFFFF
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    v = e >>> 32 &&& 0xFFFFFFFF
    sc0 = scratch
    fl0 = scratch_bits >>> 3
    scratch = scratch >>> (fl0 <<< 3)
    scratch_bits = scratch_bits &&& 7
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    v = e >>> 64 &&& 0xFFFFFFFF
    sc1 = scratch
    fl1 = scratch_bits >>> 3
    scratch = scratch >>> (fl1 <<< 3)
    scratch_bits = scratch_bits &&& 7
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    v = e >>> 96 &&& 0xFFFFFFFF
    sc2 = scratch
    fl2 = scratch_bits >>> 3
    scratch = scratch >>> (fl2 <<< 3)
    scratch_bits = scratch_bits &&& 7
    scratch = scratch ||| v <<< scratch_bits
    scratch_bits = scratch_bits + 32
    flush = scratch_bits >>> 3

    data =
      <<data::binary, sc0::little-size(fl0)-unit(8), sc1::little-size(fl1)-unit(8),
        sc2::little-size(fl2)-unit(8), scratch::little-size(flush)-unit(8)>>

    scratch = scratch >>> (flush <<< 3)
    scratch_bits = scratch_bits &&& 7
    w_ludicrous_state_keys(rest, data, scratch, scratch_bits)
  end

  defp r_ludicrous_state_keys(0, acc, _data, _num_bits, bits_read),
    do: {bits_read, Enum.reverse(acc)}

  defp r_ludicrous_state_keys(remaining, acc, data, num_bits, bits_read) do
    rv = rdw(data, bits_read, 49)
    v = rv &&& 0xFFFFFFFF
    bits_read = bits_read + 32
    w = v
    rv = rdw(data, bits_read, 49)
    v = rv &&& 0xFFFFFFFF
    bits_read = bits_read + 32
    w = w ||| v <<< 32
    rv = rdw(data, bits_read, 49)
    v = rv &&& 0xFFFFFFFF
    bits_read = bits_read + 32
    w = w ||| v <<< 64
    rv = rd(data, bits_read, 32)
    v = rv
    bits_read = bits_read + 32
    w = w ||| v <<< 96
    e = w
    r_ludicrous_state_keys(remaining - 1, [e | acc], data, num_bits, bits_read)
  end

  # The port's 40-bit window decode (issue #167): enough for a 7-bit offset
  # plus a 32-bit group, small enough that no intermediate ever boxes. The
  # callers have already priced the read inside num_bits, so the tail
  # fallback decodes exactly the bytes that exist.
  defp rd(data, bits_read, bits) do
    i = bits_read >>> 3

    window =
      case data do
        <<_::binary-size(^i), w::little-40, _::binary>> -> w
        <<_::binary-size(^i), rest::binary>> -> :binary.decode_unsigned(rest, :little)
      end

    window >>> (bits_read &&& 7) &&& (1 <<< bits) - 1
  end

  # The wide window decode: 56 bits, enough for a 7-bit offset plus a
  # 49-bit group, and still under the 2^59 fixnum boundary — one match
  # context serves a whole group of fields instead of one per field. A
  # 64-bit window would box and measures slower than the reads it saves.
  defp rdw(data, bits_read, bits) do
    i = bits_read >>> 3

    window =
      case data do
        <<_::binary-size(^i), w::little-56, _::binary>> -> w
        <<_::binary-size(^i), rest::binary>> -> :binary.decode_unsigned(rest, :little)
      end

    window >>> (bits_read &&& 7) &&& (1 <<< bits) - 1
  end
end
